INSERT INTO `artikels` (`id`, `judul`, `slug`, `konten`, `gambar`, `created_at`, `updated_at`) VALUES
(1, 'INFORMATIKA DAN KETERAMPILAN GENERIK', 'informatika-dan-keterampilan-generik', 'Pengertian Informatika\r\n\r\nInformatika adalah ilmu yang mempelajari tentang bagaimana data diolah menjadi informasi dengan bantuan teknologi, khususnya komputer. Informatika tidak hanya berkaitan dengan penggunaan komputer, tetapi juga cara berpikir untuk menyelesaikan masalah secara logis, sistematis, dan efisien.', '[\"1786022342_6a7489c6b06fa.jpg\"]', '2026-08-06 19:42:12', '2026-08-06 20:19:02'),
(2, 'BERPIKIR KRITIS', 'berpikir-kritis', 'Adalah kemampuan menganalisis informasi, menilai kebenaran, dan membuat keputusan dengan tepat sebelum percaya atau menyebarkannya.\r\n\r\nBerpikir Kritis sangat penting karena di era digital, banyak informasi beredar dengan cepat dan tidak semua benar. berpikir kritis membantu kita menghindari dari HOAX, Penipuan dan berita palsu', '[\"1786022525_6a748a7dbc321.jfif\"]', '2026-08-06 20:22:05', '2026-08-06 20:22:05'),
(3, 'Dampak Sosial Informatika', 'dampak-sosial-informatika', 'A. Pengertian Dampak Sosial Informatika\r\nAdalah pengaruh yang ditimbulkan oleh penggunaan teknologi informasi dan komunikasi\r\nterhadap kehidupan masyarakat\r\nB. Dampak Positif Informatika\r\n1. Kemudahan Akses Informasi\r\nTeknologi informatika memungkinkan masyarakat memperoleh informasi dengan cepat dan\r\nmudah melalui internet.\r\n2. Efisiensi Waktu dan Tenaga\r\nAktivitas seperti belajar, bekerja, dan berbelanja dapat dilakukan secara daring tanpa harus\r\nbertatap muka langsung.\r\n3. Meningkatkan Kualitas Pendidikan\r\nSumber belajar digital seperti video pembelajaran, e-book, dan platform edukasi membantu\r\nsiswa memahami materi dengan lebih baik.\r\n4. Mendorong Inovasi dan Kreativitas\r\nTeknologi membuka peluang bagi masyarakat untuk berinovasi, misalnya dalam pembuatan\r\naplikasi, konten digital, dan bisnis online.\r\n5. Memperluas Jaringan Sosial\r\nMedia sosial memungkinkan seseorang berinteraksi dengan orang lain dari berbagai daerah dan\r\nnegara.\r\nC. Dampak Negatif Informatika\r\n1. Penyalahgunaan Teknologi\r\nPenggunaan teknologi tanpa pengawasan dapat menyebabkan penyebaran informasi palsu\r\n(hoaks), penipuan online, dan kejahatan siber.\r\n2. Kecanduan Gadget dan Media Sosial\r\nPenggunaan berlebihan dapat mengganggu kesehatan mental, menurunkan produktivitas, dan\r\nmengurangi interaksi sosial langsung.\r\n3. Pelanggaran Privasi\r\nData pribadi pengguna dapat disalahgunakan oleh pihak yang tidak bertanggung jawab.\r\n4. Ketimpangan Akses Teknologi\r\nTidak semua masyarakat memiliki akses yang sama terhadap teknologi, sehingga menimbulkan\r\nkesenjangan digital.\r\n5. Menurunnya Nilai Sosial dan Budaya\r\nPengaruh budaya asing melalui internet dapat menggeser nilai-nilai lokal dan kebiasaan\r\nmasyarakat.\r\nD. Upaya Mengatasi Dampak Negatif Informatika\r\n1. Pendidikan Literasi Digital\r\nMasyarakat perlu dibekali kemampuan untuk menggunakan teknologi secara bijak dan\r\nbertanggung jawab.\r\n2. Pengawasan dan Regulasi\r\nPemerintah dan lembaga terkait perlu membuat aturan untuk melindungi pengguna dari\r\nkejahatan siber.\r\n3. Etika dalam Penggunaan Teknologi\r\nPengguna harus menghormati privasi orang lain, tidak menyebarkan hoaks, dan menggunakan\r\nmedia sosial secara positif.\r\n4. Pembatasan Waktu Penggunaan Gadget\r\nMenetapkan waktu khusus untuk menggunakan perangkat digital agar tidak mengganggu\r\naktivitas lain.\r\n5. Pemanfaatan Teknologi untuk Kebaikan\r\nMenggunakan teknologi untuk kegiatan produktif seperti belajar, berbisnis, dan berkreasi.\r\nE. Contoh Kasus Dampak Sosial Informatika\r\n1. Kasus Positif:\r\nSeorang pelajar menggunakan media sosial untuk berbagi konten edukatif dan menginspirasi\r\nteman-temannya belajar.\r\n2. Kasus Negatif:\r\nPenyebaran berita palsu di media sosial menyebabkan keresahan di masyarakat.\r\nF. Kesimpulan\r\nInformatika memberikan banyak manfaat bagi kehidupan manusia, namun juga menimbulkan\r\ntantangan sosial yang perlu dihadapi dengan bijak. Pemahaman dan penerapan etika digital sangat\r\npenting agar teknologi dapat digunakan untuk meningkatkan kualitas hidup tanpa merugikan orang\r\nlain.', '[\"1786069439_6a7541bf722c4.png\"]', '2026-08-07 09:23:59', '2026-08-07 09:23:59');
